-- ============================================================
-- ORDEM 3 de 10 · respostas-200
-- Quando: depois do 01
-- O que faz: carrega as 200 respostas do algoritmo, já aprovadas
-- Pode rodar de novo: sim, mas ele SOBRESCREVE edições feitas no painel e volta tudo para aprovada (se repetir depois do 08, rode o 08 de novo em seguida)
-- ============================================================

on conflict (id) do update set tema=excluded.tema, camada=excluded.camada, pergunta=excluded.pergunta, palavras_chave=excluded.palavras_chave, reflexao=excluded.reflexao, orientacao=excluded.orientacao, relacionados=excluded.relacionados, status=excluded.status;
on conflict (resposta_id) do update set origem_interna=excluded.origem_interna;

select status, count(*) from public.respostas group by status;
