insert into public.respostas (id, tema, camada, pergunta, palavras_chave, reflexao, orientacao, relacionados, status) values
($q$LID-001$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$Tenho receio de delegar e perder o controle$q$, $q$delegar; delegação; autonomia; confiar; controle$q$, $q$Quem assume uma área precisa de autonomia plena dentro dela. O líder delega no momento certo, mas o rumo e o destino continuam sendo dele.$q$, $q$Escolha a pessoa pela capacidade técnica, pela capacidade de se relacionar e pela ambição de fazer bem. Combine o resultado esperado, defina pontos de acompanhamento e deixe o caminho com ela.$q$, $q$Escolha de pessoas; Unidade de ação$q$, 'aprovada'),
($q$LID-002$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$Minha equipe não está alinhada$q$, $q$alinhamento; unidade de ação; equipe dispersa; objetivo$q$, $q$A unidade de ação nasce quando o líder tem claro aonde quer chegar e a equipe adere à ideia, sentindo-se parte da construção.$q$, $q$Faça uma reunião semanal curta em que a equipe apresenta problemas e possíveis soluções, todos opinam e os responsáveis por cada ação ficam definidos.$q$, $q$Reuniões; Comunicação$q$, 'aprovada'),
($q$LID-003$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$Como formar pessoas na minha equipe?$q$, $q$formar pessoas; desenvolver; treinar; exemplo$q$, $q$A empresa líder também é uma escola de negócios e de vida, e a formação das pessoas passa pelo exemplo do líder.$q$, $q$Entregue responsabilidades crescentes, acompanhe de perto, incentive treinamentos internos e externos e peça que cada pessoa enxergue, na rotina, o que pode melhorar.$q$, $q$Formação de líderes; Desenvolvimento contínuo$q$, 'aprovada'),
($q$LID-004$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$Vou apresentar no encontro mensal do Conquistando a Perfeição. Como me preparo?$q$, $q$apresentação; encontro mensal; ação bem-sucedida; Conquistando a Perfeição$q$, $q$O encontro serve para compartilhar o que deu certo, analisar a experiência e apontar melhorias. Todos são alunos e professores.$q$, $q$Escolha uma ação concreta, descreva o resultado, explique o que aprendeu e leve uma melhoria possível para o próximo período.$q$, $q$Práticas do período; Compartilhamento$q$, 'aprovada'),
($q$LID-005$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$Como escolher alguém para minha equipe?$q$, $q$contratar; selecionar; escolha; perfil$q$, $q$Quem entra passa a fazer parte do negócio. Alguém desalinhado com a visão do líder pode desestabilizar o grupo.$q$, $q$Avalie três coisas: capacidade técnica, capacidade de relação e ambição de sucesso. Verifique também se a pessoa se identifica com a cultura humanista da empresa.$q$, $q$Delegação; Cultura$q$, 'aprovada'),
($q$LID-006$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$O processo funciona. Preciso mesmo melhorar?$q$, $q$melhoria contínua; processo; inovação; manter$q$, $q$Primeiro mantém-se o nível atingido, fazendo certo de primeira. É na melhoria que se mede o sucesso, e ela começa pela inovação.$q$, $q$Reduza as variações do processo, pergunte à equipe onde ele trava e teste uma melhoria pequena, medindo o resultado antes de ampliar.$q$, $q$Excelência; Qualidade$q$, 'aprovada'),
($q$LID-007$q$, $q$Liderança$q$, $q$Liderança geral + cultura$q$, $q$Minha equipe resiste à mudança$q$, $q$mudança; resistência; novo processo; acomodação$q$, $q$Para mudar, é preciso entender como a cultura atual se formou. A resistência costuma vir do medo de perder algo.$q$, $q$Explique o motivo, mostre o ganho para a equipe, envolva as pessoas nos detalhes e comece por um passo pequeno. Se funcionar, compartilhe com outras equipes.$q$, $q$Comunicação; Melhoria contínua$q$, 'aprovada'),
($q$LID-008$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Como dar um feedback difícil?$q$, $q$feedback; correção; conversa difícil; chamar atenção$q$, $q$Todos precisam saber o que fazem bem e o que precisa melhorar, quanto antes melhor. Feedback honesto é cuidado, não ataque.$q$, $q$Converse em particular, descreva o fato e não a pessoa, diga o impacto, ouça a versão dela e combine uma ação concreta.$q$, $q$Relacionamentos; Ouvir$q$, 'aprovada'),
($q$LID-009$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$Quem é o meu cliente?$q$, $q$cliente; servir; fornecedor; visão global$q$, $q$O cliente não é só quem compra. Inclui o fornecedor, a comunidade vizinha e o próprio colaborador. Saber servir é organizar as relações para o melhor resultado.$q$, $q$Liste quem recebe o resultado do seu trabalho, pergunte o que cada um precisa e ajuste uma rotina para atendê-los melhor.$q$, $q$Saber servir; Visão global$q$, 'aprovada'),
($q$LID-010$q$, $q$Liderança$q$, $q$Liderança geral + cultura$q$, $q$Preciso decidir e estou inseguro$q$, $q$decisão; medo; incerteza; risco$q$, $q$Líderes convivem com a incerteza e precisam de tolerância à ambiguidade e de persistência. Adiar também é decidir.$q$, $q$Liste as opções e o pior cenário, ouça quem será afetado, defina um prazo e decida. Depois, acompanhe o resultado e ajuste.$q$, $q$Persistência; Decisões$q$, 'aprovada'),
($q$LID-011$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Como motivar uma equipe desanimada?$q$, $q$motivação; desânimo; equipe desmotivada; energia$q$, $q$A desmotivação quase sempre tem causa: falta de sentido, de reconhecimento ou de clareza. Antes de motivar, é preciso entender o que está faltando.$q$, $q$Converse com cada pessoa, ouça o que pesa, reconheça avanços recentes e conecte o trabalho do dia ao resultado maior da equipe.$q$, $q$Reconhecimento; Visão$q$, 'aprovada'),
($q$LID-012$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Fui promovido e agora lidero ex-colegas$q$, $q$promoção; novo líder; ex-colegas; transição$q$, $q$Mudar de papel muda a relação. O respeito vem da coerência e da justiça, não do cargo.$q$, $q$Converse com cada um sobre como vão trabalhar juntos, seja justo nas decisões, mantenha a proximidade sem favoritismo e peça apoio dos mais experientes.$q$, $q$Relacionamentos; Autoridade$q$, 'aprovada'),
($q$LID-013$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Dois membros da equipe estão em conflito$q$, $q$conflito; briga; desentendimento; mediar$q$, $q$Conflito não tratado cresce. O líder precisa agir cedo, com foco no problema e não nas pessoas.$q$, $q$Ouça cada um separadamente, depois reúna os dois, esclareça fatos e impacto no trabalho e combine acordos concretos com data de revisão.$q$, $q$Comunicação; Relacionamentos$q$, 'aprovada'),
($q$LID-014$q$, $q$Liderança$q$, $q$Liderança geral + cultura$q$, $q$O que significa liderar pelo exemplo?$q$, $q$exemplo; coerência; postura; credibilidade$q$, $q$A equipe copia o que o líder faz. A formação das pessoas passa pelo exemplo, e a coerência sustenta a credibilidade.$q$, $q$Escolha um comportamento que você cobra e pratique-o primeiro. Peça à equipe que aponte quando você sair do combinado.$q$, $q$Formação de pessoas; Caráter$q$, 'aprovada'),
($q$LID-015$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Tudo é urgente. Como priorizar?$q$, $q$prioridade; urgência; tempo; foco$q$, $q$Se tudo é prioridade, nada é. A urgência não é o mesmo que importância.$q$, $q$Liste as tarefas, separe o que impacta o resultado do que é só barulho, escolha as 3 principais do dia e combine com a equipe o que ficará para depois.$q$, $q$Organização; Tempo$q$, 'aprovada'),
($q$LID-016$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$Como conduzir uma reunião semanal de alinhamento?$q$, $q$reunião; alinhamento semanal; pauta; equipe$q$, $q$Na rotina da empresa, as reuniões semanais servem para a equipe apresentar problemas e soluções, com todos podendo opinar.$q$, $q$Defina pauta curta, peça que cada pessoa traga um problema e uma proposta, registre responsáveis e prazos e feche com o que será acompanhado na semana seguinte.$q$, $q$Unidade de ação; Plano de ação$q$, 'aprovada'),
($q$LID-017$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Como lidar com um colaborador de baixo desempenho?$q$, $q$baixo desempenho; resultado; cobrança; performance$q$, $q$Antes de concluir que a pessoa não serve, verifique se ela sabe o que se espera, se tem condições e se recebeu feedback claro.$q$, $q$Alinhe expectativas por escrito, combine metas curtas, ofereça apoio ou treinamento e acompanhe com frequência. Se não houver evolução, decida com justiça.$q$, $q$Feedback; Formação$q$, 'aprovada'),
($q$LID-018$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$Como reconhecer o trabalho da equipe?$q$, $q$reconhecimento; reconhecer; elogio; valorização; destaque; destacou$q$, $q$Reconhecer fortalece o protagonismo e mostra o que a cultura valoriza. Boas práticas reconhecidas viram referência para outros.$q$, $q$Elogie com fatos, diga o impacto do trabalho e, quando a prática for boa, leve-a ao encontro mensal ou à newsletter para que outras equipes aprendam.$q$, $q$Compartilhamento; Newsletter$q$, 'aprovada'),
($q$LID-019$q$, $q$Liderança$q$, $q$Liderança geral + cultura$q$, $q$Como preparar alguém para me substituir?$q$, $q$sucessor; substituto; formar líderes; mentoria$q$, $q$O legado do líder se mede pelos líderes que ele forma. Se só você consegue liderar, a organização fica frágil.$q$, $q$Identifique 1 ou 2 pessoas com potencial, dê responsabilidades crescentes e reserve um encontro regular para conversar sobre as decisões.$q$, $q$Formação de líderes; Mentoria$q$, 'aprovada'),
($q$LID-020$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Como ouvir melhor a minha equipe?$q$, $q$ouvir; escuta; diálogo; opinião$q$, $q$Ouvir não é esperar a vez de falar. É entender o que a pessoa quer dizer e o que ela precisa.$q$, $q$Pergunte mais do que afirma, não interrompa, repita com suas palavras o que entendeu e agradeça sugestões, mesmo as que não forem adotadas.$q$, $q$Comunicação; Empatia$q$, 'aprovada'),
($q$LID-021$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Preciso comunicar uma decisão impopular$q$, $q$decisão impopular; comunicar; notícia ruim; transparência$q$, $q$As pessoas aceitam melhor uma decisão difícil quando entendem o motivo e se sentem respeitadas.$q$, $q$Explique o porquê com clareza, assuma a responsabilidade, ouça as reações sem se defender e diga o que acontece a partir de agora.$q$, $q$Transparência; Mudança$q$, 'aprovada'),
($q$LID-022$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Como liderar equipes em turnos diferentes?$q$, $q$turnos; equipes; horários; alinhamento$q$, $q$Equipes separadas por horário correm o risco de viver realidades distintas. A comunicação precisa chegar igual a todos.$q$, $q$Defina um ponto de passagem de informações entre turnos, padronize os registros e faça encontros periódicos com representantes de cada turno.$q$, $q$Comunicação; Unidade de ação$q$, 'aprovada'),
($q$LID-023$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$A equipe errou. Eu assumo ou cobro?$q$, $q$erro; responsabilidade; culpa; falha da equipe$q$, $q$O líder responde pelo resultado do time. Assumir diante dos outros e corrigir com a pessoa em particular constrói respeito.$q$, $q$Resolva o problema primeiro, entenda a causa com a equipe e ajuste o processo para o erro não se repetir.$q$, $q$Responsabilidade; Feedback$q$, 'aprovada'),
($q$LID-024$q$, $q$Liderança$q$, $q$Liderança geral + cultura$q$, $q$Como fazer a equipe entender para onde estamos indo?$q$, $q$visão; meta; direção; objetivo$q$, $q$A unidade de ação exige que o líder tenha claro aonde quer chegar e que a equipe adira. Uma visão só funciona quando é compartilhada.$q$, $q$Explique a meta em uma frase, mostre o progresso nas reuniões e conecte o trabalho de cada um ao resultado final da empresa.$q$, $q$Propósito; Metas$q$, 'aprovada'),
($q$LID-025$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Posso liderar sem ter cargo de chefia?$q$, $q$liderar sem cargo; influência; liderança 360; liderar para cima$q$, $q$Liderança é influência, não título. É possível liderar para cima, para os lados e para baixo.$q$, $q$Entregue o que prometeu, ajude os colegas a ter sucesso e leve soluções ao seu gestor, não só problemas.$q$, $q$Influência; Atitude$q$, 'aprovada'),
($q$LID-026$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Como me relacionar bem com o meu chefe?$q$, $q$chefe; gestor; liderar para cima; alinhamento$q$, $q$Liderar para cima é facilitar o trabalho de quem decide: clareza, confiança e antecipação.$q$, $q$Entenda as prioridades do seu gestor, informe cedo o que for importante, traga propostas e não só problemas e peça feedback com regularidade.$q$, $q$Comunicação; Confiança$q$, 'aprovada'),
($q$LID-027$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Faço tudo sozinho e não tenho tempo$q$, $q$sobrecarga; falta de tempo; fazer tudo; operacional$q$, $q$Um líder que faz tudo vira o limite do próprio time. O trabalho do líder inclui formar e organizar, não só executar.$q$, $q$Liste suas tarefas, separe o que só você pode fazer, delegue o restante com instruções claras e reserve um horário fixo para planejar.$q$, $q$Delegação; Tempo$q$, 'aprovada'),
($q$LID-028$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Como equilibrar o dia a dia e o estratégico?$q$, $q$estratégico; operacional; planejamento; futuro$q$, $q$A rotina consome o líder se ele não protege tempo para pensar adiante.$q$, $q$Reserve um bloco semanal fixo para planejar, defina 2 ou 3 prioridades de médio prazo e acompanhe-as nas reuniões.$q$, $q$Planejamento; Prioridades$q$, 'aprovada'),
($q$LID-029$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Como lidar com a pressão por resultados?$q$, $q$pressão; resultado; meta; estresse$q$, $q$Pressão faz parte da liderança. O que decide o efeito dela é a clareza do plano e o cuidado com as pessoas.$q$, $q$Quebre a meta em etapas, comunique com transparência o que está acontecendo, peça ajuda quando precisar e reconheça os avanços da equipe.$q$, $q$Metas; Persistência$q$, 'aprovada'),
($q$LID-030$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Como criar um ambiente de confiança?$q$, $q$confiança; ambiente; transparência; segurança$q$, $q$Confiança se constrói com coerência: o que se diz e o que se faz precisam coincidir, inclusive nos erros.$q$, $q$Cumpra o que prometer, admita falhas, dê autonomia proporcional à responsabilidade e trate todos com a mesma justiça.$q$, $q$Relacionamentos; Ética$q$, 'aprovada'),
($q$LID-031$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$Como estimular a iniciativa da equipe?$q$, $q$iniciativa; protagonismo; proatividade; ideias$q$, $q$A cultura da empresa valoriza o protagonismo. As pessoas se sentem donas do resultado quando podem propor e executar.$q$, $q$Peça sugestões de melhoria, deixe a pessoa conduzir a ação, reconheça a iniciativa e leve boas ideias ao encontro mensal.$q$, $q$Protagonismo; Melhoria contínua$q$, 'aprovada'),
($q$LID-032$q$, $q$Liderança$q$, $q$Liderança geral + cultura$q$, $q$Como integrar um novo colaborador?$q$, $q$integração; novo colaborador; onboarding; acolher$q$, $q$O novo integrante passa a fazer parte do negócio. O início define a relação dele com a equipe e com a cultura.$q$, $q$Apresente a equipe e a cultura, combine expectativas claras, indique um colega de apoio e acompanhe com conversas curtas nas primeiras semanas.$q$, $q$Cultura; Formação de pessoas$q$, 'aprovada'),
($q$LID-033$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$Como replicar uma boa prática de outra equipe?$q$, $q$boa prática; replicar; compartilhar; referência$q$, $q$Na empresa, as melhorias de uma equipe muitas vezes são replicadas por outras. Compartilhar é parte da cultura.$q$, $q$Entenda o que deu certo e por quê, adapte à realidade da sua equipe, teste em pequena escala e depois compartilhe o resultado.$q$, $q$Compartilhamento; Newsletter$q$, 'aprovada'),
($q$LID-034$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Como acompanhar o desempenho da equipe?$q$, $q$desempenho; acompanhamento; indicadores; metas$q$, $q$O que não é acompanhado não melhora. Medir ajuda a conversar com fatos, não com impressões.$q$, $q$Escolha poucos indicadores claros, acompanhe-os com frequência, converse sobre o resultado com a equipe e comemore as evoluções.$q$, $q$Metas; Feedback$q$, 'aprovada'),
($q$LID-035$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$Como dar autonomia sem perder a qualidade?$q$, $q$autonomia; qualidade; liberdade; padrão$q$, $q$Autonomia plena funciona dentro de um campo bem definido. Primeiro se mantém o nível atingido, depois se melhora.$q$, $q$Defina o padrão de qualidade e os limites, dê liberdade no caminho e acompanhe pelos resultados, não por controle excessivo.$q$, $q$Delegação; Qualidade$q$, 'aprovada'),
($q$LID-036$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Um colaborador antigo resiste às novas ideias$q$, $q$colaborador antigo; resistência; experiência; novas ideias$q$, $q$A experiência é valiosa, mas pode virar acomodação. Respeitar o passado ajuda a construir o novo.$q$, $q$Reconheça a contribuição da pessoa, peça a opinião dela sobre o novo, dê um papel na mudança e mostre ganhos concretos.$q$, $q$Mudança; Respeito$q$, 'aprovada'),
($q$LID-037$q$, $q$Liderança$q$, $q$Liderança geral + cultura$q$, $q$A equipe não se compromete. O que fazer?$q$, $q$comprometimento; compromisso; engajamento; responsabilidade$q$, $q$Comprometimento nasce quando a pessoa vê sentido e se sente parte da construção, não apenas executora.$q$, $q$Explique o propósito do trabalho, envolva a equipe no plano, defina responsáveis e prazos e cobre com coerência.$q$, $q$Unidade de ação; Engajamento$q$, 'aprovada'),
($q$LID-038$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$Como equilibrar resultado e pessoas?$q$, $q$resultado; pessoas; equilíbrio; humanista$q$, $q$A empresa busca conciliar resultado econômico e desenvolvimento humanista. Uma dimensão alimenta a outra.$q$, $q$Ao decidir, pergunte qual o impacto no resultado e nas pessoas. Invista em formação e reconheça avanços, sem perder o foco nas metas.$q$, $q$Cultura; Propósito$q$, 'aprovada'),
($q$LID-039$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$Como me manter atualizado como líder?$q$, $q$atualização; aprendizado; estudar; inovação$q$, $q$O líder tem sede de conhecimento e entende que a inovação contínua é a base das organizações modernas.$q$, $q$Reserve tempo semanal para aprender, converse com pessoas de outras áreas, participe de treinamentos e traga o que aprender para a equipe.$q$, $q$Aprendizado; Inovação$q$, 'aprovada'),
($q$LID-040$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Cometi um erro. Como lidar?$q$, $q$meu erro; humildade; reconhecer erro; corrigir$q$, $q$Reconhecer o erro mostra maturidade e ensina a equipe a fazer o mesmo.$q$, $q$Assuma com objetividade, corrija o que for possível, explique o que aprendeu e ajuste o processo para não repetir.$q$, $q$Humildade; Responsabilidade$q$, 'aprovada'),
($q$LID-041$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Como liderar em um momento de crise?$q$, $q$crise; emergência; pressão; clareza$q$, $q$Na crise, a equipe procura direção. Calma, clareza e comunicação frequente fazem diferença.$q$, $q$Defina o essencial, dê instruções simples, comunique com frequência, escute quem está na linha de frente e registre os aprendizados depois.$q$, $q$Decisões; Comunicação$q$, 'aprovada'),
($q$LID-042$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Como distribuir tarefas com justiça?$q$, $q$distribuir tarefas; justiça; carga de trabalho; equilíbrio$q$, $q$Justiça na divisão do trabalho sustenta a confiança. Favoritismo, mesmo percebido, corrói a equipe.$q$, $q$Use critérios claros (competência, carga e desenvolvimento), explique-os à equipe e revise a distribuição periodicamente.$q$, $q$Delegação; Ética$q$, 'aprovada'),
($q$LID-043$q$, $q$Liderança$q$, $q$Liderança geral$q$, $q$Como cuidar da minha energia como líder?$q$, $q$energia; equilíbrio; cansaço; foco$q$, $q$O líder precisa de energia para sustentar o grupo. Quem se descuida de si acaba descuidando da equipe.$q$, $q$Defina limites para o trabalho, proteja horários de descanso, priorize o que importa e peça apoio quando estiver sobrecarregado.$q$, $q$Equilíbrio; Prioridades$q$, 'aprovada'),
($q$LID-044$q$, $q$Liderança$q$, $q$Cultura Beira Rio$q$, $q$Como estimular o aprendizado entre os colegas?$q$, $q$aprender; ensinar; troca; alunos e professores$q$, $q$Na cultura da empresa, todos são alunos e professores ao mesmo tempo, e o conhecimento circula.$q$, $q$Peça que cada pessoa ensine algo que domina, crie momentos curtos de troca na equipe e valorize quem compartilha.$q$, $q$Conquistando a Perfeição; Formação$q$, 'aprovada'),
($q$LID-045$q$, $q$Liderança$q$, $q$Liderança geral + cultura$q$, $q$Como definir metas claras para a equipe?$q$, $q$metas; objetivos; resultado esperado; clareza$q$, $q$Metas claras criam unidade de ação: cada pessoa sabe onde chegar e o que sua parte representa.$q$, $q$Escreva a meta de forma simples e mensurável, combine prazos e responsáveis, explique o porquê e acompanhe o progresso.$q$, $q$Visão; Plano de ação$q$, 'aprovada'),
($q$CUL-001$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$O que é o Conquistando a Perfeição?$q$, $q$Conquistando a Perfeição; programa; o que é; desenvolvimento$q$, $q$É o programa que faz parte da rotina da empresa e busca o desenvolvimento contínuo das pessoas e o surgimento de novos talentos em todas as áreas.$q$, $q$Participe dos encontros mensais, apresente o que deu certo no seu trabalho e leve uma melhoria possível para o período seguinte.$q$, $q$Encontro mensal; Protagonismo$q$, 'aprovada'),
($q$CUL-002$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$Para que serve o encontro mensal?$q$, $q$encontro mensal; reunião; apresentar; compartilhar$q$, $q$Ali os colaboradores apresentam ações bem-sucedidas, analisam as experiências com os colegas e apontam melhorias para o futuro.$q$, $q$Prepare uma ação concreta, conte o resultado e o que aprendeu, ouça os colegas e anote o que pode aplicar na sua rotina.$q$, $q$Conquistando a Perfeição; Compartilhamento$q$, 'aprovada'),
($q$CUL-003$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$Qual é a missão da Beira Rio e o que ela tem a ver com o meu trabalho?$q$, $q$missão; propósito; beleza; desenvolvimento humano$q$, $q$A missão é oferecer beleza para os pés com soluções criativas e produtos de qualidade, agregando valor e contribuindo para o desenvolvimento humano.$q$, $q$Pergunte-se como o seu trabalho do dia contribui para a qualidade do produto ou para o desenvolvimento de alguém, e faça isso com cuidado.$q$, $q$Visão; Valores$q$, 'aprovada'),
($q$CUL-004$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$Qual é a visão da empresa e qual é o meu papel nela?$q$, $q$visão; futuro; maior e melhor; crescimento$q$, $q$A visão é ser a maior e melhor empresa de calçados, com produtos reconhecidos no mundo e profissionais que garantam um futuro inovador.$q$, $q$Escolha uma melhoria na sua área que aproxime a empresa desse futuro e leve-a ao seu líder ou ao encontro mensal.$q$, $q$Missão; Melhoria contínua$q$, 'aprovada'),
($q$CUL-005$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$O que significa 'saber servir'?$q$, $q$saber servir; servir; funcionalidade; relações$q$, $q$É organizar funções e relações para que o resultado seja máximo, atendendo bem quem depende do seu trabalho.$q$, $q$Identifique quem recebe o resultado do seu trabalho, pergunte o que precisa e ajuste uma rotina para servir melhor.$q$, $q$Cliente; Unidade de ação$q$, 'aprovada'),
($q$CUL-006$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$Por que a empresa fala tanto em desenvolvimento humano?$q$, $q$desenvolvimento humano; pessoas; crescimento; humanista$q$, $q$Para a cultura da empresa, as pessoas são o maior bem, e grandes empresas são feitas por grandes pessoas.$q$, $q$Invista no seu aprendizado, ajude um colega a crescer e leve ao seu líder uma ideia de desenvolvimento para a equipe.$q$, $q$Formação de pessoas; Propósito$q$, 'aprovada'),
($q$CUL-007$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$O que é protagonismo no meu dia a dia?$q$, $q$protagonismo; iniciativa; responsabilidade; autor$q$, $q$É assumir o papel de autor do resultado do seu trabalho, em vez de esperar que outros resolvam.$q$, $q$Escolha um problema pequeno da sua rotina, proponha uma solução, execute com o apoio do líder e conte o resultado.$q$, $q$Iniciativa; Conquistando a Perfeição$q$, 'aprovada'),
($q$CUL-008$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$O que significa ser aluno e professor ao mesmo tempo?$q$, $q$aluno; professor; aprender; ensinar$q$, $q$Na cultura da empresa, todos aprendem e ensinam: o conhecimento circula entre as pessoas.$q$, $q$Compartilhe algo que você domina, pergunte a quem sabe mais e valorize quem ensina.$q$, $q$Troca de conhecimento; Formação$q$, 'aprovada'),
($q$CUL-009$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$Como ligar o meu trabalho aos valores da empresa?$q$, $q$valores; trabalho; coerência; dia a dia$q$, $q$Os valores falam em excelência que gera resultado para clientes, colaboradores, fornecedores, comunidade, investidores e meio ambiente.$q$, $q$Escolha um valor por semana e observe como seu trabalho o reflete. Se algo destoar, converse com seu líder.$q$, $q$Ética; Excelência$q$, 'aprovada'),
($q$CUL-010$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$O que é excelência empresarial para a Beira Rio?$q$, $q$excelência; resultado; qualidade; empresa$q$, $q$É buscar resultados positivos que beneficiem todos os públicos da empresa, e não apenas o lucro.$q$, $q$Ao concluir uma tarefa, pergunte quem se beneficia dela e se ela foi feita da melhor forma possível.$q$, $q$Qualidade; Resultados$q$, 'aprovada'),
($q$CUL-011$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$Como posso contribuir para preservar o meio ambiente no meu setor?$q$, $q$meio ambiente; sustentabilidade; natureza; desperdício$q$, $q$Um dos valores da empresa é preservar o meio ambiente, com processos que protejam a essência e os princípios da natureza.$q$, $q$Observe desperdícios na sua rotina, sugira melhorias de processo e leve a prática ao encontro mensal.$q$, $q$Valores; Melhoria contínua$q$, 'aprovada'),
($q$CUL-012$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$Como a empresa apoia a comunidade e como posso ajudar?$q$, $q$comunidade; sociedade; apoio local; vizinhança$q$, $q$Apoiar o desenvolvimento da comunidade local é um dos valores da empresa, e a comunidade vizinha faz parte de quem a empresa serve.$q$, $q$Converse com seu líder sobre iniciativas locais, participe das ações e leve ideias que envolvam a comunidade.$q$, $q$Valores; Cliente$q$, 'aprovada'),
($q$CUL-013$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$Como posso fortalecer nossos fornecedores?$q$, $q$fornecedor; parceiro; relação; cadeia$q$, $q$Fortalecer fornecedores faz parte dos valores da empresa. Eles também fazem parte de quem a empresa serve.$q$, $q$Seja claro nos pedidos, cumpra prazos combinados, dê retorno sobre a qualidade e trate o fornecedor como parceiro.$q$, $q$Cliente; Saber servir$q$, 'aprovada'),
($q$CUL-014$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$Como posso satisfazer o cliente e o consumidor no meu setor?$q$, $q$cliente; consumidor; satisfação; qualidade$q$, $q$Satisfazer clientes e consumidores é um valor central. Mesmo quem não os atende diretamente tem clientes internos.$q$, $q$Descubra quem usa o resultado do seu trabalho, pergunte o que precisa e ajuste uma rotina para atender melhor.$q$, $q$Saber servir; Qualidade$q$, 'aprovada'),
($q$CUL-015$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$O que é unidade de ação?$q$, $q$unidade de ação; equipe; objetivo comum; adesão$q$, $q$É quando as pessoas têm o mesmo objetivo e se sentem parte da construção do resultado, cada uma com sua inteligência.$q$, $q$Converse com a equipe sobre o objetivo, defina responsáveis e acompanhe o andamento nas reuniões semanais.$q$, $q$Alinhamento; Reuniões$q$, 'aprovada'),
($q$CUL-016$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$Como a cultura entra na rotina da minha equipe?$q$, $q$cultura; rotina; prática; dia a dia$q$, $q$A cultura vive nas práticas repetidas: reuniões, encontros, reconhecimento e melhoria contínua.$q$, $q$Escolha uma prática simples, como a reunião semanal ou o registro de melhorias, e mantenha-a com constância.$q$, $q$Práticas; Conquistando a Perfeição$q$, 'aprovada'),
($q$CUL-017$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$A empresa é só um negócio ou é algo mais?$q$, $q$empresa; negócio; escola; propósito$q$, $q$Na cultura descrita, a empresa também é uma escola de negócios e de vida, que concilia resultado econômico e desenvolvimento humanista.$q$, $q$Veja o trabalho como lugar de resultado e de aprendizado. Pergunte-se o que aprendeu hoje e o que ensinou.$q$, $q$Desenvolvimento humano; Excelência$q$, 'aprovada'),
($q$CUL-018$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$Por que a melhoria contínua faz parte da cultura?$q$, $q$melhoria contínua; processo; evolução; mudança$q$, $q$Primeiro se mantém o nível atingido, depois se melhora. A melhoria é onde se mede o sucesso e começa pela inovação.$q$, $q$Registre uma melhoria por mês no seu setor, teste em pequena escala e compartilhe com outras equipes.$q$, $q$Excelência; Inovação$q$, 'aprovada'),
($q$CUL-019$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$A cultura muda quando a empresa cresce?$q$, $q$crescimento; mudança de cultura; manter; evolução$q$, $q$Mudar uma cultura começa por entender a cultura atual e como ela se formou. O crescimento exige cuidar do que é essencial.$q$, $q$Reforce os valores nas decisões, converse com os novos sobre como as coisas são feitas e preserve as práticas que funcionam.$q$, $q$Valores; Mudança$q$, 'aprovada'),
($q$CUL-020$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$O que a empresa espera de quem lidera?$q$, $q$líder; expectativa; formação; exemplo$q$, $q$Que dê exemplo, forme pessoas, delegue com coerência, busque a unidade de ação e se atualize sempre.$q$, $q$Avalie-se em cada ponto, escolha um para melhorar este mês e peça feedback à equipe.$q$, $q$Liderança; Exemplo$q$, 'aprovada'),
($q$CUL-021$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$Como identificar uma boa prática para levar ao encontro?$q$, $q$boa prática; identificar; resultado; compartilhar$q$, $q$Uma boa prática é uma ação que trouxe resultado e pode ser aprendida por outros.$q$, $q$Pergunte: funcionou, por que funcionou e outro setor pode aplicar? Se sim, descreva o antes, o depois e o aprendizado.$q$, $q$Encontro mensal; Newsletter$q$, 'aprovada'),
($q$CUL-022$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$O que faço quando vejo algo fora da nossa cultura?$q$, $q$desvio; conduta; falha; cultura$q$, $q$Cuidar da cultura é responsabilidade de todos, e a melhoria começa em conversas honestas.$q$, $q$Converse com a pessoa envolvida, se possível, ou com seu líder, com fatos e sem acusar, e proponha uma saída.$q$, $q$Ética; Feedback$q$, 'aprovada'),
($q$CUL-023$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$Por que fazer certo de primeira é tão importante?$q$, $q$qualidade; certo de primeira; erro; retrabalho$q$, $q$Manter o nível atingido exige fazer certo de primeira, com poucas variações no processo.$q$, $q$Antes de entregar, confira o essencial, padronize o que funciona e avise cedo quando perceber um problema.$q$, $q$Qualidade; Melhoria contínua$q$, 'aprovada'),
($q$CUL-024$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$Como a empresa equilibra tradição e inovação?$q$, $q$inovação; tradição; novas tecnologias; mudança$q$, $q$A empresa se apoia em gestão eficaz, novas tecnologias e novos materiais, mantendo a base de valores.$q$, $q$Aprenda novas ferramentas do seu setor e preserve o que é essencial: qualidade, cuidado e respeito às pessoas.$q$, $q$Inovação; Excelência$q$, 'aprovada'),
($q$CUL-025$q$, $q$Cultura$q$, $q$Cultura Beira Rio$q$, $q$O que quer dizer 'espalhar beleza pelo mundo'?$q$, $q$beleza; espalhar; propósito; consumidor$q$, $q$Quer dizer que cada produto carrega o cuidado das pessoas que o fazem, e que a empresa deseja encantar o consumidor.$q$, $q$Antes de concluir sua etapa, pergunte se faria com orgulho para alguém que você ama. Isso é cuidado com a beleza.$q$, $q$Missão; Qualidade$q$, 'aprovada'),
($q$REL-001$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como me comunicar com mais clareza?$q$, $q$comunicação; clareza; explicar; entender$q$, $q$Comunicar bem é fazer o outro entender, e não apenas falar. A clareza começa por saber o que se quer dizer.$q$, $q$Defina a ideia principal antes de falar, use exemplos, confirme se a pessoa entendeu e ajuste a explicação se preciso.$q$, $q$Ouvir; Reuniões$q$, 'aprovada'),
($q$REL-002$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como pedir ajuda a um colega?$q$, $q$pedir ajuda; colega; apoio; cooperação$q$, $q$Pedir ajuda não é fraqueza: é um jeito de aprender e de fortalecer a equipe.$q$, $q$Seja específico sobre o que precisa, explique o motivo, respeite o tempo do colega e agradeça depois.$q$, $q$Cooperação; Gratidão$q$, 'aprovada'),
($q$REL-003$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como lidar com fofoca no trabalho?$q$, $q$fofoca; fofoqueiro; fofocar; boato; comentário; clima$q$, $q$A fofoca destrói a confiança e quase sempre distorce os fatos.$q$, $q$Não repasse boatos, redirecione a conversa e, quando algo for sério, fale diretamente com a pessoa ou com o líder.$q$, $q$Confiança; Ética$q$, 'aprovada'),
($q$REL-004$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como dizer não sem criar conflito?$q$, $q$dizer não; limite; recusar; pedido$q$, $q$Dizer não com respeito protege a qualidade do que você entrega e a relação com o outro.$q$, $q$Explique o motivo, reconheça a necessidade do pedido e, se possível, ofereça uma alternativa ou outro prazo.$q$, $q$Comunicação; Prioridades$q$, 'aprovada'),
($q$REL-005$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como lidar com um colega difícil?$q$, $q$colega difícil; relação; conflito; paciência$q$, $q$Muitas vezes o problema está no comportamento e não na pessoa. Entender o contexto ajuda a agir melhor.$q$, $q$Foque em fatos, mantenha calma e respeito, combine regras de convivência e, se não funcionar, peça apoio ao líder.$q$, $q$Conflitos; Respeito$q$, 'aprovada'),
($q$REL-006$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como pedir desculpas de forma sincera?$q$, $q$desculpa; pedir perdão; erro; reparar$q$, $q$Um pedido sincero reconhece o erro, assume a responsabilidade e busca reparar.$q$, $q$Diga o que fez, assuma sem justificativas excessivas, ouça o outro e combine como evitar que se repita.$q$, $q$Humildade; Confiança$q$, 'aprovada'),
($q$REL-007$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como seguir em frente depois de uma mágoa no trabalho?$q$, $q$mágoa; ressentimento; perdoar; superar$q$, $q$Guardar ressentimento pesa mais em quem o carrega. Perdoar não é concordar, é seguir em frente.$q$, $q$Converse com a pessoa se possível, estabeleça limites claros e foque no trabalho que vocês precisam entregar.$q$, $q$Perdão; Respeito$q$, 'aprovada'),
($q$REL-008$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como lidar com uma crítica que recebi?$q$, $q$crítica; feedback; receber; ouvir$q$, $q$É preciso humildade para ouvir uma crítica e sabedoria para usá-la.$q$, $q$Ouça sem interromper, peça exemplos, agradeça e decida o que vai mudar. Se não concordar, converse com calma.$q$, $q$Feedback; Humildade$q$, 'aprovada'),
($q$REL-009$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como fazer uma crítica a um colega sem ofender?$q$, $q$criticar colega; observação; respeito; conversa$q$, $q$Uma crítica bem feita ajuda o outro a crescer e preserva a relação.$q$, $q$Converse em particular, descreva o fato, explique o impacto e pergunte como ele vê a situação.$q$, $q$Feedback; Respeito$q$, 'aprovada'),
($q$REL-010$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como construir confiança com um novo colega?$q$, $q$confiança; novo colega; relação; começo$q$, $q$A confiança nasce de atitudes pequenas e constantes: cumprir o combinado, ser honesto e respeitar.$q$, $q$Seja claro, cumpra prazos, ajude quando puder e valorize o que o colega sabe fazer.$q$, $q$Integração; Ética$q$, 'aprovada'),
($q$REL-011$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como trabalhar com quem pensa diferente?$q$, $q$pensar diferente; diversidade; discordar; respeito$q$, $q$As diferenças bem tratadas enriquecem as soluções. O desafio é discordar sem desrespeitar.$q$, $q$Pergunte o que a pessoa vê que você não vê, procure pontos em comum e decidam juntos com base em fatos.$q$, $q$Respeito; Comunicação$q$, 'aprovada'),
($q$REL-012$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Sinto inveja ou competição de um colega$q$, $q$inveja; competição; rivalidade; comparação$q$, $q$A comparação constante drena energia. O sucesso do colega não tira o seu.$q$, $q$Use a admiração como aprendizado, foque em seu próprio desenvolvimento e comemore as conquistas do grupo.$q$, $q$Equilíbrio; Gratidão$q$, 'aprovada'),
($q$REL-013$q$, $q$Relacionamentos$q$, $q$Liderança geral + cultura$q$, $q$Como demonstrar gratidão no trabalho?$q$, $q$gratidão; agradecer; reconhecimento; valorizar$q$, $q$Agradecer faz o outro se sentir visto e fortalece o clima da equipe. É também uma forma de reconhecer.$q$, $q$Agradeça com fatos, diga o que a ajuda possibilitou e, quando fizer sentido, leve o reconhecimento ao encontro mensal.$q$, $q$Reconhecimento; Cultura$q$, 'aprovada'),
($q$REL-014$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como convencer alguém sem impor?$q$, $q$convencer; persuadir; argumento; influência$q$, $q$Persuadir é ajudar o outro a enxergar valor em uma ideia, não ganhar uma discussão.$q$, $q$Entenda o que importa para a pessoa, apresente benefícios que se ligam a isso e deixe espaço para dúvidas.$q$, $q$Comunicação; Influência$q$, 'aprovada'),
($q$REL-015$q$, $q$Relacionamentos$q$, $q$Liderança geral + cultura$q$, $q$Como me relacionar com outras áreas da empresa?$q$, $q$outras áreas; interdependência; cooperação; setores$q$, $q$Os setores dependem uns dos outros. O resultado final é construído em conjunto.$q$, $q$Conheça o trabalho das áreas parceiras, alinhe prazos e necessidades, e compartilhe aprendizados com elas.$q$, $q$Unidade de ação; Cooperação$q$, 'aprovada'),
($q$REL-016$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Um colega não entrega a parte dele$q$, $q$colega não entrega; prazo; combinado; cobrança$q$, $q$Falhas de entrega afetam toda a cadeia. Antes de cobrar, vale entender o que aconteceu.$q$, $q$Converse diretamente, pergunte se há algum obstáculo, renegocie prazos e, se continuar, envolva o líder com fatos.$q$, $q$Responsabilidade; Comunicação$q$, 'aprovada'),
($q$REL-017$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como ser mais empático?$q$, $q$empatia; entender o outro; sensibilidade; escuta$q$, $q$Empatia é tentar compreender a situação do outro antes de julgar.$q$, $q$Pergunte como a pessoa está, ouça com atenção e considere o contexto dela antes de reagir.$q$, $q$Ouvir; Respeito$q$, 'aprovada'),
($q$REL-018$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como evitar mal-entendidos em mensagens?$q$, $q$mensagem; WhatsApp; texto; mal-entendido$q$, $q$Mensagens perdem tom e contexto. Um texto curto pode ser lido de várias formas.$q$, $q$Seja claro e objetivo, evite ironia, e para assuntos delicados prefira uma conversa direta.$q$, $q$Comunicação; Clareza$q$, 'aprovada'),
($q$REL-019$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como lidar com minha irritação no trabalho?$q$, $q$irritação; raiva; estresse; controle emocional$q$, $q$A irritação passa, mas as palavras ditas nela ficam. Reconhecer o sinal ajuda a agir melhor.$q$, $q$Faça uma pausa, respire, volte ao assunto quando estiver mais calmo e peça desculpas se exagerou.$q$, $q$Equilíbrio; Respeito$q$, 'aprovada'),
($q$REL-020$q$, $q$Relacionamentos$q$, $q$Liderança geral + cultura$q$, $q$Como construir boas relações entre turnos e setores?$q$, $q$turnos; setores; integração; passagem de informação$q$, $q$Equipes que se conhecem colaboram melhor. A passagem de informações precisa ser clara.$q$, $q$Combine um registro simples de passagem, participe de encontros entre turnos e reconheça o trabalho de quem vem antes e depois.$q$, $q$Unidade de ação; Comunicação$q$, 'aprovada'),
($q$REL-021$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como incentivar um colega desanimado?$q$, $q$incentivar; colega desanimado; encorajar; apoio$q$, $q$Encorajar é lembrar a pessoa do que ela é capaz e mostrar que ela não está sozinha.$q$, $q$Ouça com atenção, reconheça os esforços, ofereça ajuda concreta e valorize os pequenos avanços.$q$, $q$Encorajamento; Empatia$q$, 'aprovada'),
($q$REL-022$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Tivemos um mal-entendido. Como resolver?$q$, $q$mal-entendido; confusão; esclarecer; conversa$q$, $q$Muitos conflitos nascem de interpretações diferentes. Esclarecer cedo evita que cresçam.$q$, $q$Converse logo, pergunte como a pessoa entendeu, explique sua intenção e combine como evitar novas confusões.$q$, $q$Comunicação; Conflitos$q$, 'aprovada'),
($q$REL-023$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como me posicionar em uma reunião?$q$, $q$reunião; posicionar; falar; opinião$q$, $q$Participar com opinião preparada ajuda a equipe e mostra comprometimento.$q$, $q$Prepare dois ou três pontos, fale com objetivo, ouça os demais e use exemplos do seu trabalho.$q$, $q$Comunicação; Protagonismo$q$, 'aprovada'),
($q$REL-024$q$, $q$Relacionamentos$q$, $q$Liderança geral$q$, $q$Como discordar mantendo o respeito?$q$, $q$discordar; divergência; respeito; debate$q$, $q$Discordar faz parte do trabalho em equipe. O respeito está em atacar a ideia, não a pessoa.$q$, $q$Reconheça o que concorda, explique o que vê diferente, use fatos e aceite a decisão do grupo ou do líder.$q$, $q$Respeito; Comunicação$q$, 'aprovada'),
($q$REL-025$q$, $q$Relacionamentos$q$, $q$Liderança geral + cultura$q$, $q$Como me relacionar com colegas de gerações diferentes?$q$, $q$gerações; mais velho; mais novo; diferença de idade$q$, $q$Gerações diferentes trazem experiência e novidades. Na cultura da empresa, todos aprendem e ensinam.$q$, $q$Pergunte, troque saberes, evite estereótipos e valorize o que cada um tem a oferecer.$q$, $q$Aluno e professor; Respeito$q$, 'aprovada'),
($q$TRA-001$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Como organizar meu dia de trabalho?$q$, $q$organizar; rotina; dia; planejamento$q$, $q$Um dia bem organizado começa antes de começar: com clareza sobre o que precisa ser entregue.$q$, $q$Ao chegar, liste as tarefas, escolha as 3 mais importantes, reserve horários para elas e deixe margem para imprevistos.$q$, $q$Prioridades; Planejamento$q$, 'aprovada'),
($q$TRA-002$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Tenho muitas tarefas. Por onde começo?$q$, $q$muitas tarefas; começar; prioridade; urgência$q$, $q$Começar pelo que mais importa evita que o urgente consuma o dia.$q$, $q$Separe o que impacta o resultado do que é secundário, comece pela mais importante e peça ajuda ao líder se o conjunto for inviável.$q$, $q$Foco; Tempo$q$, 'aprovada'),
($q$TRA-003$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Como manter o foco sem me distrair?$q$, $q$foco; distração; concentração; atenção$q$, $q$O foco se treina e é protegido com pequenas decisões.$q$, $q$Reduza interrupções, trabalhe em blocos curtos, deixe o celular fora de alcance e faça pausas breves entre os blocos.$q$, $q$Produtividade; Rotina$q$, 'aprovada'),
($q$TRA-004$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Como cumprir prazos?$q$, $q$prazo; entrega; atraso; compromisso$q$, $q$Cumprir prazo é cumprir um combinado, e isso constrói confiança.$q$, $q$Divida a entrega em etapas, estime o tempo com folga, acompanhe o andamento e avise cedo se algo puder atrasar.$q$, $q$Compromisso; Responsabilidade$q$, 'aprovada'),
($q$TRA-005$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Como planejar a minha semana?$q$, $q$planejar semana; semana; metas; agenda$q$, $q$Planejar não toma tempo: economiza. Uma semana sem plano é uma semana reativa.$q$, $q$No início da semana, defina as principais entregas, distribua nos dias e reserve um momento no fim para avaliar o que foi feito.$q$, $q$Organização; Metas$q$, 'aprovada'),
($q$TRA-006$q$, $q$Trabalho$q$, $q$Liderança geral + cultura$q$, $q$Como transformar um problema em solução?$q$, $q$problema; solução; resolver; proatividade$q$, $q$Quem vê o problema com clareza já está a meio caminho da solução. Trazer propostas, e não só reclamações, é protagonismo.$q$, $q$Descreva o problema com fatos, busque as causas, proponha duas ou três opções e leve ao líder ou ao encontro mensal.$q$, $q$Protagonismo; Melhoria contínua$q$, 'aprovada'),
($q$TRA-007$q$, $q$Trabalho$q$, $q$Liderança geral + cultura$q$, $q$Como trabalhar melhor em equipe?$q$, $q$trabalho em equipe; cooperação; time; colaboração$q$, $q$O resultado final é fruto de muitas pessoas. A unidade de ação faz a equipe render mais do que a soma de cada uma.$q$, $q$Conheça o objetivo comum, combine responsabilidades, avise sobre dificuldades e valorize o que cada um traz.$q$, $q$Unidade de ação; Cooperação$q$, 'aprovada'),
($q$TRA-008$q$, $q$Trabalho$q$, $q$Cultura Beira Rio$q$, $q$Como fazer um bom plano de ação?$q$, $q$plano de ação; responsáveis; prazos; execução$q$, $q$Na rotina da empresa, o que é proposto ganha responsáveis para colocá-lo em prática.$q$, $q$Escreva o que será feito, quem faz, até quando e como se saberá que deu certo. Revise nas reuniões.$q$, $q$Reuniões; Metas$q$, 'aprovada'),
($q$TRA-009$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Como lidar com a procrastinação?$q$, $q$procrastinar; adiar; deixar para depois; preguiça$q$, $q$Adiar costuma esconder medo de errar ou de não saber começar. O primeiro passo pequeno quebra a inércia.$q$, $q$Divida a tarefa em partes, comece por 10 minutos, defina um prazo e comemore o avanço.$q$, $q$Disciplina; Foco$q$, 'aprovada'),
($q$TRA-010$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Como ser mais produtivo sem me sobrecarregar?$q$, $q$produtividade; sobrecarga; eficiência; equilíbrio$q$, $q$Produtividade é fazer o que importa bem feito, não fazer mais coisas.$q$, $q$Elimine o que não agrega, agrupe tarefas parecidas, proteja pausas e converse com o líder se a carga ficar excessiva.$q$, $q$Prioridades; Equilíbrio$q$, 'aprovada'),
($q$TRA-011$q$, $q$Trabalho$q$, $q$Cultura Beira Rio$q$, $q$Como pedir treinamento ao meu líder?$q$, $q$treinamento; capacitação; aprender; pedir$q$, $q$A empresa incentiva a formação das pessoas, e pedir treinamento mostra interesse em crescer.$q$, $q$Explique qual habilidade quer desenvolver, como isso melhora seu trabalho e proponha uma forma de aplicar o aprendizado.$q$, $q$Formação; Desenvolvimento$q$, 'aprovada'),
($q$TRA-012$q$, $q$Trabalho$q$, $q$Cultura Beira Rio$q$, $q$Como crescer na carreira dentro da empresa?$q$, $q$carreira; crescer; promoção; desenvolvimento$q$, $q$A formação de líderes na empresa é interna e baseada em meritocracia: resultado, aprendizado e alinhamento com a cultura contam.$q$, $q$Entregue com qualidade, aprenda sempre, assuma responsabilidades, mostre alinhamento à cultura e converse com seu líder sobre seus objetivos.$q$, $q$Formação de líderes; Protagonismo$q$, 'aprovada'),
($q$TRA-013$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Fui mudado de função ou área. Como me adapto?$q$, $q$mudança de função; nova área; adaptação; recomeçar$q$, $q$Mudar é desconfortável, mas também uma oportunidade de aprender.$q$, $q$Pergunte muito, observe quem domina a função, peça feedback nas primeiras semanas e registre o que aprende.$q$, $q$Mudança; Aprendizado$q$, 'aprovada'),
($q$TRA-014$q$, $q$Trabalho$q$, $q$Cultura Beira Rio$q$, $q$Como registrar o que aprendi no trabalho?$q$, $q$registrar aprendizado; anotar; memória; lições$q$, $q$Registrar transforma experiência em aprendizado e prepara o que será compartilhado no encontro mensal.$q$, $q$Anote, ao fim de cada semana, uma ação que deu certo, o motivo e o que repetir. Use isso no encontro mensal.$q$, $q$Conquistando a Perfeição; Evolução$q$, 'aprovada'),
($q$TRA-015$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Como entregar com qualidade sob pressão?$q$, $q$pressão; qualidade; urgência; pouco tempo$q$, $q$A pressão revela hábitos: quem tem processo e preparação mantém a qualidade.$q$, $q$Priorize o essencial, confirme o que é crítico, peça clareza sobre o que pode esperar e evite pular etapas de conferência.$q$, $q$Qualidade; Foco$q$, 'aprovada'),
($q$TRA-016$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Como lidar com tarefas repetitivas?$q$, $q$tarefa repetitiva; rotina; monotonia; tédio$q$, $q$A rotina sustenta a empresa, e é nela que a melhoria contínua acontece.$q$, $q$Procure pequenas melhorias no processo, registre ideias e proponha ao líder. Assim a rotina vira aprendizado.$q$, $q$Melhoria contínua; Rotina$q$, 'aprovada'),
($q$TRA-017$q$, $q$Trabalho$q$, $q$Cultura Beira Rio$q$, $q$Como padronizar o meu trabalho?$q$, $q$padronizar; padrão; processo; repetir$q$, $q$Manter o nível atingido exige poucas variações no processo e fazer certo de primeira.$q$, $q$Documente os passos que funcionam, siga-os com disciplina e proponha ajustes quando encontrar algo melhor.$q$, $q$Qualidade; Melhoria contínua$q$, 'aprovada'),
($q$TRA-018$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Como me preparar para uma reunião de resultados?$q$, $q$reunião de resultados; preparar; apresentar; números$q$, $q$Quem chega preparado participa melhor e ajuda a decidir.$q$, $q$Reúna os números principais, explique o que mudou e por quê, destaque dificuldades e prepare uma proposta.$q$, $q$Reuniões; Comunicação$q$, 'aprovada'),
($q$TRA-019$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Como lidar com interrupções?$q$, $q$interrupção; atrapalhar; foco; chamadas$q$, $q$Nem toda interrupção pode ser evitada, mas dá para reduzi-las e gerenciá-las.$q$, $q$Combine horários de atendimento, avise quando estiver em tarefa crítica e retome o que estava fazendo com um registro rápido.$q$, $q$Foco; Organização$q$, 'aprovada'),
($q$TRA-020$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Recebi uma nova responsabilidade. E agora?$q$, $q$nova responsabilidade; assumir; desafio; expectativa$q$, $q$Assumir mais responsabilidade é sinal de confiança e exige clareza.$q$, $q$Alinhe expectativas com o líder, mapeie o que precisa aprender, defina os primeiros passos e peça feedback cedo.$q$, $q$Responsabilidade; Aprendizado$q$, 'aprovada'),
($q$TRA-021$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Como acompanhar o resultado do que eu faço?$q$, $q$resultado; acompanhar; medir; indicador$q$, $q$O que não é acompanhado não melhora. Medir ajuda a conversar com fatos.$q$, $q$Escolha um ou dois indicadores simples do seu trabalho, anote semanalmente e leve a evolução ao seu líder.$q$, $q$Metas; Melhoria$q$, 'aprovada'),
($q$TRA-022$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Preciso fazer uma tarefa que não sei fazer$q$, $q$não sei fazer; aprender; dúvida; ajuda$q$, $q$Admitir que não sabe é o primeiro passo para aprender, e na cultura todos são alunos e professores.$q$, $q$Pergunte a quem sabe, peça para ver o processo uma vez, anote os passos e pratique com acompanhamento.$q$, $q$Aluno e professor; Humildade$q$, 'aprovada'),
($q$TRA-023$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Como manter o local de trabalho organizado?$q$, $q$organização; ambiente; local de trabalho; limpeza$q$, $q$Um ambiente organizado reduz erros e desperdício, e demonstra cuidado com o trabalho.$q$, $q$Mantenha cada coisa em seu lugar, descarte o que não usa, deixe o posto pronto para o próximo e sugira melhorias.$q$, $q$Qualidade; Cuidado$q$, 'aprovada'),
($q$TRA-024$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Como dividir tarefas em uma equipe?$q$, $q$dividir tarefas; divisão; equipe; responsabilidades$q$, $q$Dividir bem significa considerar competência, carga e desenvolvimento de cada pessoa.$q$, $q$Liste as tarefas, converse sobre quem faz melhor o quê, equilibre a carga e revise a divisão periodicamente.$q$, $q$Cooperação; Justiça$q$, 'aprovada'),
($q$TRA-025$q$, $q$Trabalho$q$, $q$Liderança geral$q$, $q$Como encerrar bem o dia e passar pendências?$q$, $q$encerrar o dia; pendências; passagem; continuidade$q$, $q$Terminar bem o dia permite recomeçar com clareza e protege quem assume depois.$q$, $q$Registre o que foi feito, o que ficou pendente e o que é urgente. Comunique ao próximo responsável de forma clara.$q$, $q$Comunicação; Organização$q$, 'aprovada'),
($q$EXC-001$q$, $q$Excelência$q$, $q$Cultura Beira Rio$q$, $q$O que é excelência no meu trabalho?$q$, $q$excelência; fazer bem feito; padrão; qualidade$q$, $q$Para a empresa, a excelência é buscar resultados positivos que beneficiem clientes, colaboradores e a sociedade, e começa no trabalho bem feito.$q$, $q$Pergunte-se, em cada entrega, se ela foi feita da melhor forma possível e quem se beneficia dela.$q$, $q$Qualidade; Valores$q$, 'aprovada'),
($q$EXC-002$q$, $q$Excelência$q$, $q$Cultura Beira Rio$q$, $q$Como melhorar um pouco todos os dias?$q$, $q$melhorar todo dia; evolução; pequenos passos; constância$q$, $q$A melhoria contínua é parte da cultura: pequenos avanços repetidos geram grandes resultados.$q$, $q$Escolha um ponto de melhoria por semana, aplique, avalie e registre. No fim do mês, leve ao encontro.$q$, $q$Melhoria contínua; Constância$q$, 'aprovada'),
($q$EXC-003$q$, $q$Excelência$q$, $q$Liderança geral$q$, $q$Como manter a disciplina?$q$, $q$disciplina; compromisso; rotina; constância$q$, $q$Disciplina é fazer o que precisa ser feito, mesmo sem vontade, porque o objetivo importa.$q$, $q$Defina rotinas simples, comece pelo mais importante, registre o cumprimento e comemore a regularidade.$q$, $q$Hábitos; Foco$q$, 'aprovada'),
($q$EXC-004$q$, $q$Excelência$q$, $q$Liderança geral$q$, $q$Como ser constante?$q$, $q$constância; regularidade; persistência; ritmo$q$, $q$Constância vale mais do que intensidade. Resultados duráveis vêm da repetição.$q$, $q$Escolha ações pequenas que consiga manter, vincule a horários fixos e retome logo se falhar.$q$, $q$Disciplina; Persistência$q$, 'aprovada'),
($q$EXC-005$q$, $q$Excelência$q$, $q$Liderança geral$q$, $q$Como não desistir diante de uma dificuldade?$q$, $q$desistir; dificuldade; persistência; obstáculo$q$, $q$Persistência é uma característica do líder e de quem constrói resultados.$q$, $q$Divida o obstáculo em partes, busque ajuda, ajuste o caminho sem mudar o objetivo e lembre por que começou.$q$, $q$Perseverança; Superação$q$, 'aprovada'),
($q$EXC-006$q$, $q$Excelência$q$, $q$Liderança geral$q$, $q$Como superar um fracasso?$q$, $q$fracasso; derrota; recomeçar; superar$q$, $q$O fracasso é informação. O que importa é o que se aprende e a decisão de seguir.$q$, $q$Analise o que aconteceu sem se culpar, tire duas lições, ajuste o plano e dê o próximo passo.$q$, $q$Erros; Superação$q$, 'aprovada'),
($q$EXC-007$q$, $q$Excelência$q$, $q$Liderança geral$q$, $q$Como criar bons hábitos no trabalho?$q$, $q$hábitos; rotina; mudar; comportamento$q$, $q$Hábitos nascem da repetição. Pequenas mudanças diárias transformam resultados.$q$, $q$Escolha um hábito de cada vez, associe a um horário, acompanhe e mantenha por pelo menos algumas semanas.$q$, $q$Disciplina; Constância$q$, 'aprovada'),
($q$EXC-008$q$, $q$Excelência$q$, $q$Liderança geral$q$, $q$Como evitar a acomodação?$q$, $q$acomodação; mediocridade; zona de conforto; estagnação$q$, $q$A acomodação aparece quando se deixa de questionar o que pode melhorar.$q$, $q$Pergunte-se o que pode ser melhor na sua rotina, procure aprender algo novo e busque desafios dentro da sua área.$q$, $q$Melhoria contínua; Atualização$q$, 'aprovada'),
($q$EXC-009$q$, $q$Excelência$q$, $q$Liderança geral$q$, $q$Como medir o meu progresso?$q$, $q$medir progresso; evolução; indicador; resultado$q$, $q$O que se mede melhora. Acompanhar a evolução motiva e orienta.$q$, $q$Escolha um indicador que represente seu trabalho, anote semanalmente e compare mês a mês.$q$, $q$Metas; Evolução$q$, 'aprovada'),
($q$EXC-010$q$, $q$Excelência$q$, $q$Liderança geral$q$, $q$Como aprender com os meus erros?$q$, $q$aprender com erros; falha; lição; corrigir$q$, $q$Errar faz parte do aprendizado quando se transforma em melhoria.$q$, $q$Reconheça o erro, entenda a causa, corrija o que for possível e ajuste o processo para não repetir.$q$, $q$Humildade; Melhoria$q$, 'aprovada'),
($q$EXC-011$q$, $q$Excelência$q$, $q$Liderança geral$q$, $q$Como manter a qualidade quando estou cansado?$q$, $q$cansaço; qualidade; atenção; desgaste$q$, $q$O cansaço aumenta o risco de erro. Cuidar da energia protege a qualidade.$q$, $q$Faça pausas, revise o que é crítico, peça apoio quando estiver sobrecarregado e cuide do descanso.$q$, $q$Energia; Qualidade$q$, 'aprovada'),
($q$EXC-012$q$, $q$Excelência$q$, $q$Cultura Beira Rio$q$, $q$Buscar a perfeição não paralisa?$q$, $q$perfeição; perfeccionismo; paralisia; melhoria$q$, $q$No programa da empresa, a perfeição é uma busca contínua e não um ponto final: cada passo é uma conquista.$q$, $q$Defina o que é bom o suficiente para entregar, entregue, colha feedback e melhore na etapa seguinte.$q$, $q$Conquistando a Perfeição; Melhoria contínua$q$, 'aprovada'),
($q$EXC-013$q$, $q$Excelência$q$, $q$Liderança geral + cultura$q$, $q$Como celebrar conquistas sem relaxar?$q$, $q$celebrar; conquista; comemorar; manter ritmo$q$, $q$Celebrar reconhece o esforço e fortalece a equipe, mas a evolução continua.$q$, $q$Reconheça o que foi alcançado, compartilhe com quem ajudou e defina a próxima meta antes de encerrar a comemoração.$q$, $q$Reconhecimento; Metas$q$, 'aprovada'),
($q$EXC-014$q$, $q$Excelência$q$, $q$Liderança geral + cultura$q$, $q$Como estabelecer padrões altos para minha equipe?$q$, $q$padrão alto; exigência; equipe; qualidade$q$, $q$Padrões altos funcionam quando são claros, possíveis e acompanhados pelo exemplo do líder.$q$, $q$Explique o padrão e o motivo, mostre na prática, dê feedback regular e reconheça quem o mantém.$q$, $q$Exemplo; Qualidade$q$, 'aprovada'),
($q$EXC-015$q$, $q$Excelência$q$, $q$Liderança geral$q$, $q$O resultado não vem. O que fazer?$q$, $q$resultado não vem; frustração; ajuste; estratégia$q$, $q$Quando o resultado não vem, o caminho pode precisar de ajuste, não o objetivo.$q$, $q$Revise o plano, converse com quem já conseguiu, teste uma mudança por vez e acompanhe os efeitos.$q$, $q$Persistência; Melhoria$q$, 'aprovada'),
($q$EXC-016$q$, $q$Excelência$q$, $q$Cultura Beira Rio$q$, $q$Como transformar uma ideia em melhoria real?$q$, $q$ideia; melhoria; implementar; testar$q$, $q$As ideias valem quando saem do papel. Na empresa, as melhorias de uma equipe muitas vezes são replicadas por outras.$q$, $q$Descreva a ideia, teste em pequena escala, meça o resultado, ajuste e compartilhe a prática.$q$, $q$Inovação; Compartilhamento$q$, 'aprovada'),
($q$EXC-017$q$, $q$Excelência$q$, $q$Liderança geral$q$, $q$Como ter mais dedicação ao que faço?$q$, $q$dedicação; empenho; vontade; comprometimento$q$, $q$A dedicação cresce quando se enxerga sentido no que se faz.$q$, $q$Conecte sua tarefa ao resultado para quem a recebe, busque aprender mais sobre ela e se desafie a fazê-la melhor.$q$, $q$Propósito; Compromisso$q$, 'aprovada'),
($q$EXC-018$q$, $q$Excelência$q$, $q$Liderança geral$q$, $q$Como manter a motivação a longo prazo?$q$, $q$motivação; longo prazo; energia; propósito$q$, $q$A motivação oscila. Propósito e pequenas vitórias sustentam a caminhada.$q$, $q$Defina metas de curto prazo, reconheça avanços, mantenha-se aprendendo e converse com pessoas que o inspiram.$q$, $q$Propósito; Constância$q$, 'aprovada'),
($q$EXC-019$q$, $q$Excelência$q$, $q$Liderança geral$q$, $q$Tenho medo de errar. Como superar?$q$, $q$medo de errar; erro; insegurança; coragem$q$, $q$O medo de errar paralisa mais que o erro em si. Quem tenta aprende.$q$, $q$Comece por passos pequenos, peça orientação antes de decisões maiores e trate cada erro como fonte de aprendizado.$q$, $q$Coragem; Aprendizado$q$, 'aprovada'),
($q$EXC-020$q$, $q$Excelência$q$, $q$Cultura Beira Rio$q$, $q$Como equilibrar velocidade e qualidade?$q$, $q$velocidade; qualidade; rapidez; certo de primeira$q$, $q$Fazer certo de primeira costuma ser mais rápido do que refazer. A pressa sem processo gera retrabalho.$q$, $q$Padronize o que dá, defina o que precisa de conferência e avise cedo quando o prazo estiver em risco.$q$, $q$Qualidade; Prazo$q$, 'aprovada'),
($q$ETI-001$q$, $q$Ética$q$, $q$Cultura Beira Rio$q$, $q$O que é agir com ética no meu trabalho?$q$, $q$ética; agir certo; conduta; integridade$q$, $q$Os valores da empresa falam em resultados positivos para todos os públicos. Agir com ética é considerar o impacto das suas ações em cada um deles.$q$, $q$Antes de decidir, pergunte: isto é honesto, é justo com todos e eu faria diante de qualquer pessoa? Se a resposta for não, pare e converse com seu líder.$q$, $q$Valores; Integridade$q$, 'aprovada'),
($q$ETI-002$q$, $q$Ética$q$, $q$Liderança geral$q$, $q$Vi um colega fazendo algo errado. O que faço?$q$, $q$colega errado; conduta; denúncia; falha$q$, $q$Ignorar o erro pode prejudicar pessoas e a própria cultura. A forma de agir faz diferença.$q$, $q$Se for seguro, converse com o colega com fatos e sem acusar. Se for grave, ou não resolver, leve ao seu líder ou ao canal indicado pela empresa.$q$, $q$Responsabilidade; Feedback$q$, 'aprovada'),
($q$ETI-003$q$, $q$Ética$q$, $q$Liderança geral$q$, $q$Como ser honesto sem magoar?$q$, $q$honestidade; sinceridade; verdade; cuidado$q$, $q$Honestidade e respeito andam juntos. Dizer a verdade com cuidado é um sinal de confiança.$q$, $q$Fale sobre fatos, escolha o momento certo, mostre o que é possível melhorar e ouça a reação da pessoa.$q$, $q$Feedback; Respeito$q$, 'aprovada'),
($q$ETI-004$q$, $q$Ética$q$, $q$Liderança geral$q$, $q$Cometi um deslize e ninguém percebeu. Devo contar?$q$, $q$deslize; erro escondido; contar; transparência$q$, $q$Um erro escondido costuma crescer. Assumir cedo preserva a confiança e permite corrigir.$q$, $q$Avise o responsável, explique o que ocorreu, proponha a correção e o que fará para evitar nova falha.$q$, $q$Transparência; Responsabilidade$q$, 'aprovada'),
($q$ETI-005$q$, $q$Ética$q$, $q$Liderança geral$q$, $q$Pediram para 'dar um jeitinho'. Como agir?$q$, $q$jeitinho; atalho; irregularidade; pressão$q$, $q$Atalhos que ferem regras ou valores cobram um preço depois.$q$, $q$Diga com respeito que não pode fazer assim, ofereça uma alternativa correta e, se persistir, converse com a liderança.$q$, $q$Integridade; Coragem$q$, 'aprovada'),
($q$ETI-006$q$, $q$Ética$q$, $q$Liderança geral + cultura$q$, $q$Como manter a integridade sob pressão por resultados?$q$, $q$integridade; pressão; resultado; princípios$q$, $q$Resultado só vale quando é construído de forma correta. A empresa busca resultados que beneficiem todos.$q$, $q$Mantenha seus princípios mesmo com prazos apertados, comunique dificuldades com antecedência e busque soluções legítimas.$q$, $q$Valores; Excelência$q$, 'aprovada'),
($q$ETI-007$q$, $q$Ética$q$, $q$Liderança geral$q$, $q$Como agir com justiça entre colegas?$q$, $q$justiça; igualdade; favoritismo; critérios$q$, $q$Justiça é tratar com os mesmos critérios, reconhecendo as diferenças de cada situação.$q$, $q$Explique os critérios de suas decisões, evite favoritismo e ouça os envolvidos antes de concluir.$q$, $q$Equidade; Respeito$q$, 'aprovada'),
($q$ETI-008$q$, $q$Ética$q$, $q$Cultura Beira Rio$q$, $q$Recebi um presente de fornecedor. O que fazer?$q$, $q$presente; fornecedor; conflito de interesses; brinde$q$, $q$Fortalecer fornecedores é um valor, e isso exige relações transparentes, sem favores que influenciem decisões.$q$, $q$Informe seu líder, siga as regras internas da empresa e mantenha a decisão baseada em critérios objetivos.$q$, $q$Fornecedores; Transparência$q$, 'aprovada'),
($q$ETI-009$q$, $q$Ética$q$, $q$Liderança geral$q$, $q$Como guardar sigilo de informações?$q$, $q$sigilo; confidencialidade; informação; discrição$q$, $q$Quem guarda informações com cuidado protege a empresa e as pessoas.$q$, $q$Compartilhe só o necessário, evite falar de assuntos internos fora do ambiente e use os canais corretos.$q$, $q$Confiança; Responsabilidade$q$, 'aprovada'),
($q$ETI-010$q$, $q$Ética$q$, $q$Liderança geral$q$, $q$Como cumprir o que prometo?$q$, $q$cumprir promessa; palavra; compromisso; confiabilidade$q$, $q$A palavra dada constrói reputação. Prometer menos e cumprir mais fortalece a confiança.$q$, $q$Antes de prometer, avalie se pode cumprir. Se algo mudar, avise cedo e proponha uma alternativa.$q$, $q$Compromisso; Confiança$q$, 'aprovada'),
($q$ETI-011$q$, $q$Ética$q$, $q$Liderança geral$q$, $q$O que é lealdade no trabalho?$q$, $q$lealdade; fidelidade; equipe; empresa$q$, $q$Lealdade é honrar a confiança que recebeu, e inclui dizer a verdade, mesmo quando é difícil.$q$, $q$Defenda o que é correto, fale diretamente com quem precisa ouvir e evite críticas pelas costas.$q$, $q$Confiança; Honestidade$q$, 'aprovada'),
($q$ETI-012$q$, $q$Ética$q$, $q$Liderança geral$q$, $q$Como lidar com mentiras na equipe?$q$, $q$mentira; desonestidade; equipe; confiança$q$, $q$A mentira destrói a confiança e prejudica o ambiente.$q$, $q$Converse com os envolvidos, busque os fatos, deixe claro o que é esperado e acione a liderança em casos graves.$q$, $q$Transparência; Confiança$q$, 'aprovada'),
($q$ETI-013$q$, $q$Ética$q$, $q$Liderança geral$q$, $q$Como ser transparente com a equipe?$q$, $q$transparência; clareza; informar; abertura$q$, $q$Equipes confiam mais em líderes que explicam o que pode ser explicado.$q$, $q$Compartilhe as decisões e os motivos, assuma o que não sabe e informe cedo as mudanças que afetam o grupo.$q$, $q$Comunicação; Liderança$q$, 'aprovada'),
($q$ETI-014$q$, $q$Ética$q$, $q$Liderança geral + cultura$q$, $q$O que é responsabilidade pelo resultado do grupo?$q$, $q$responsabilidade coletiva; resultado; grupo; equipe$q$, $q$Na unidade de ação, o resultado é de todos. Cada pessoa responde por sua parte e pelo todo.$q$, $q$Cumpra sua parte, avise quando perceber risco e ajude os colegas a entregarem o combinado.$q$, $q$Unidade de ação; Responsabilidade$q$, 'aprovada'),
($q$ETI-015$q$, $q$Ética$q$, $q$Cultura Beira Rio$q$, $q$Minha decisão afeta a comunidade ou o meio ambiente. E agora?$q$, $q$impacto; comunidade; meio ambiente; decisão$q$, $q$Cuidar da comunidade local e do meio ambiente está entre os valores da empresa.$q$, $q$Avalie quem será afetado, busque a alternativa de menor impacto, converse com sua liderança e registre a decisão.$q$, $q$Valores; Sustentabilidade$q$, 'aprovada'),
($q$ETI-016$q$, $q$Ética$q$, $q$Cultura Beira Rio$q$, $q$Como tratar fornecedores com ética?$q$, $q$fornecedor; parceria; respeito; negociação$q$, $q$Os fornecedores também são parte de quem a empresa serve, e a relação deve ser clara e justa.$q$, $q$Seja objetivo nos pedidos, cumpra o combinado, pague e responda com respeito e dê retorno sobre a qualidade.$q$, $q$Fornecedores; Valores$q$, 'aprovada'),
($q$ETI-017$q$, $q$Ética$q$, $q$Liderança geral$q$, $q$Como construir uma reputação sólida?$q$, $q$reputação; imagem; credibilidade; caráter$q$, $q$A reputação é formada pelas pequenas atitudes, repetidas por muito tempo.$q$, $q$Cumpra o que promete, trate todos com respeito, assuma erros e seja coerente em qualquer ambiente.$q$, $q$Caráter; Confiança$q$, 'aprovada'),
($q$ETI-018$q$, $q$Ética$q$, $q$Liderança geral$q$, $q$Qual a diferença entre influenciar e manipular?$q$, $q$manipular; influenciar; persuadir; intenção$q$, $q$Influenciar é ajudar o outro a decidir com clareza. Manipular é usar o outro para um fim próprio.$q$, $q$Seja claro sobre seu objetivo, apresente fatos, aceite um não e deixe a pessoa decidir.$q$, $q$Persuasão; Respeito$q$, 'aprovada'),
($q$ETI-019$q$, $q$Ética$q$, $q$Liderança geral + cultura$q$, $q$Como dar crédito a quem merece?$q$, $q$crédito; reconhecimento; mérito; honestidade$q$, $q$Reconhecer o mérito dos outros fortalece a cultura e a confiança. A empresa valoriza a meritocracia.$q$, $q$Cite quem contribuiu, agradeça em público quando for apropriado e leve boas práticas ao encontro mensal.$q$, $q$Reconhecimento; Meritocracia$q$, 'aprovada'),
($q$ETI-020$q$, $q$Ética$q$, $q$Liderança geral$q$, $q$E se o meu chefe agir de forma antiética?$q$, $q$chefe antiético; conduta; liderança; denúncia$q$, $q$É uma situação difícil e deve ser tratada com cuidado e fatos.$q$, $q$Registre o que ocorreu, procure primeiro uma conversa direta, se for seguro, e use os canais indicados pela empresa, como RH ou a diretoria.$q$, $q$Coragem; Responsabilidade$q$, 'aprovada'),
($q$DHU-001$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral$q$, $q$Como me conhecer melhor como profissional?$q$, $q$autoconhecimento; pontos fortes; conhecer a si; perfil$q$, $q$Conhecer seus pontos fortes e suas limitações ajuda a escolher onde crescer.$q$, $q$Anote o que faz bem, o que ainda precisa melhorar e peça a duas pessoas que opinem. Defina um ponto para desenvolver.$q$, $q$Pontos fortes; Feedback$q$, 'aprovada'),
($q$DHU-002$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral$q$, $q$Como lidar com minhas emoções no trabalho?$q$, $q$emoções; controle emocional; inteligência emocional; reagir$q$, $q$Sentir é normal. O que importa é como reagir.$q$, $q$Perceba o que sentiu, respire antes de responder, escolha o que dizer e volte ao assunto quando estiver mais calmo.$q$, $q$Equilíbrio; Relacionamentos$q$, 'aprovada'),
($q$DHU-003$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral + cultura$q$, $q$Como ter mais autoconfiança?$q$, $q$autoconfiança; insegurança; confiança em si$q$, $q$A autoconfiança é uma característica do líder e cresce com pequenas conquistas.$q$, $q$Registre o que já fez bem, prepare-se para o que é novo, comece por desafios pequenos e peça feedback.$q$, $q$Atitude; Preparação$q$, 'aprovada'),
($q$DHU-004$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral$q$, $q$Como desenvolver a humildade?$q$, $q$humildade; aprender; ouvir; ego$q$, $q$Humildade é saber que sempre há o que aprender e reconhecer o que os outros fazem bem.$q$, $q$Peça opinião, agradeça correções, reconheça seus limites e valorize o conhecimento dos colegas.$q$, $q$Aprendizado; Respeito$q$, 'aprovada'),
($q$DHU-005$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral$q$, $q$Como ganhar maturidade profissional?$q$, $q$maturidade; amadurecer; postura; experiência$q$, $q$A maturidade vem da experiência refletida: quem aprende com cada situação evolui mais rápido.$q$, $q$Ao fim de cada semana, pense no que aprendeu, converse com alguém mais experiente e assuma responsabilidades.$q$, $q$Reflexão; Responsabilidade$q$, 'aprovada'),
($q$DHU-006$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral$q$, $q$Como manter uma atitude positiva em dias difíceis?$q$, $q$atitude positiva; dia difícil; ânimo; perspectiva$q$, $q$Atitude positiva não é negar o problema: é escolher como reagir a ele.$q$, $q$Reconheça a dificuldade, identifique o que está em suas mãos, foque na próxima ação e busque apoio.$q$, $q$Resiliência; Foco$q$, 'aprovada'),
($q$DHU-007$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral$q$, $q$Como ter coragem de dizer o que penso?$q$, $q$coragem; falar; opinar; posicionar$q$, $q$Coragem é dizer o que pensa com respeito, mesmo com receio.$q$, $q$Prepare o que dirá, escolha o momento, comece com fatos e abra espaço para ouvir.$q$, $q$Comunicação; Respeito$q$, 'aprovada'),
($q$DHU-008$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral + cultura$q$, $q$Como criar um plano de desenvolvimento pessoal?$q$, $q$plano de desenvolvimento; metas; evolução; crescer$q$, $q$A empresa valoriza a formação das pessoas, e cada um é protagonista do seu crescimento.$q$, $q$Defina uma habilidade, um prazo e uma forma de praticar. Converse com seu líder e acompanhe a evolução.$q$, $q$Formação; Protagonismo$q$, 'aprovada'),
($q$DHU-009$q$, $q$Desenvolvimento humano$q$, $q$Cultura Beira Rio$q$, $q$Como aprender com quem sabe mais?$q$, $q$aprender; mentor; pessoa experiente; troca$q$, $q$Na cultura da empresa, todos são alunos e professores. Quem sabe mais também aprende ao ensinar.$q$, $q$Escolha alguém que admira, faça perguntas objetivas, peça para observar o trabalho e agradeça.$q$, $q$Aluno e professor; Mentoria$q$, 'aprovada'),
($q$DHU-010$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral$q$, $q$Como criar o hábito de ler e aprender?$q$, $q$leitura; aprender; estudar; hábito$q$, $q$Aprender todo dia, mesmo em pequenas doses, forma pessoas mais preparadas.$q$, $q$Reserve 15 minutos diários, escolha temas ligados ao seu trabalho e anote uma ideia para aplicar.$q$, $q$Atualização; Disciplina$q$, 'aprovada'),
($q$DHU-011$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral$q$, $q$Como desenvolver a curiosidade?$q$, $q$curiosidade; perguntar; explorar; aprender$q$, $q$A curiosidade abre portas para novas ideias e melhorias.$q$, $q$Pergunte por que as coisas são feitas assim, visite outras áreas e teste uma ideia pequena.$q$, $q$Inovação; Aprendizado$q$, 'aprovada'),
($q$DHU-012$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral$q$, $q$Fico nervoso antes de apresentar. O que fazer?$q$, $q$nervosismo; apresentação; falar em público; ansiedade$q$, $q$Nervosismo antes de apresentar é comum e pode ser transformado em preparação.$q$, $q$Ensaie em voz alta, conheça os dois primeiros minutos de cor, respire fundo e foque em ajudar quem ouve.$q$, $q$Comunicação; Preparação$q$, 'aprovada'),
($q$DHU-013$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral$q$, $q$Como ser mais resiliente?$q$, $q$resiliência; adversidade; superar; força$q$, $q$Resiliência é a capacidade de se reerguer e continuar. Ela se fortalece com experiência e apoio.$q$, $q$Reconheça o que aconteceu, ajuste o plano, busque apoio e valorize o que já superou.$q$, $q$Persistência; Superação$q$, 'aprovada'),
($q$DHU-014$q$, $q$Desenvolvimento humano$q$, $q$Cultura Beira Rio$q$, $q$Como encontrar propósito no meu trabalho?$q$, $q$propósito; sentido; motivação; trabalho$q$, $q$Na cultura da empresa, o trabalho é lugar de resultado e de aprendizado, e contribui para as pessoas e a sociedade.$q$, $q$Pergunte quem se beneficia do seu trabalho, o que aprende com ele e como pode melhorar a vida de alguém com ele.$q$, $q$Propósito; Missão$q$, 'aprovada'),
($q$DHU-015$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral$q$, $q$Como pedir feedback sobre mim?$q$, $q$pedir feedback; avaliação; opinião; crescer$q$, $q$Quem pede feedback cresce mais rápido. É preciso abrir espaço para ouvir.$q$, $q$Escolha uma pessoa de confiança, pergunte o que faço bem e o que posso melhorar, agradeça e aplique algo.$q$, $q$Feedback; Humildade$q$, 'aprovada'),
($q$DHU-016$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral$q$, $q$Estou frustrado por não ter sido promovido$q$, $q$frustração; promoção; carreira; expectativa$q$, $q$A frustração é natural, e pode virar informação sobre o que desenvolver.$q$, $q$Converse com seu líder sobre critérios e expectativas, peça um plano de desenvolvimento e mantenha a qualidade do trabalho.$q$, $q$Carreira; Feedback$q$, 'aprovada'),
($q$DHU-017$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral$q$, $q$Como simplificar o que faço?$q$, $q$simplificar; simples; complexidade; eficiência$q$, $q$A simplicidade é sinal de maturidade: fazer o essencial bem feito.$q$, $q$Liste suas etapas, elimine o que não agrega, padronize o que funciona e peça opinião à equipe.$q$, $q$Melhoria contínua; Foco$q$, 'aprovada'),
($q$DHU-018$q$, $q$Desenvolvimento humano$q$, $q$Cultura Beira Rio$q$, $q$Como ampliar minha visão além da minha função?$q$, $q$visão global; ampliar visão; outras áreas; contexto$q$, $q$O perfil de liderança descrito na empresa inclui visão global: entender clientes, fornecedores, comunidade e colaboradores.$q$, $q$Converse com outras áreas, entenda como o seu trabalho chega ao cliente final e traga o que aprender para sua equipe.$q$, $q$Visão global; Saber servir$q$, 'aprovada'),
($q$DHU-019$q$, $q$Desenvolvimento humano$q$, $q$Liderança geral$q$, $q$Como ser mais paciente?$q$, $q$paciência; calma; tolerância; esperar$q$, $q$Paciência é saber que processos e pessoas têm seu tempo.$q$, $q$Respire antes de reagir, tente entender o outro, divida o objetivo em etapas e comemore pequenos avanços.$q$, $q$Equilíbrio; Persistência$q$, 'aprovada'),
($q$DHU-020$q$, $q$Desenvolvimento humano$q$, $q$Cultura Beira Rio$q$, $q$Como criar o hábito de refletir sobre o meu dia?$q$, $q$refletir; reflexão; revisar o dia; aprendizado$q$, $q$A reflexão faz parte do ciclo da plataforma: conhecer, refletir, praticar. É ela que transforma experiência em aprendizado.$q$, $q$No fim do dia, anote o que deu certo, o que pode melhorar e uma ação para amanhã. Use isso no encontro mensal.$q$, $q$Conquistando a Perfeição; Evolução$q$, 'aprovada'),
($q$ONT-001$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$O que é a Ontopsicologia e por que aparece na cultura da empresa?$q$, $q$Ontopsicologia; o que é; escola; fundamento$q$, $q$É uma escola de pensamento que estuda a pessoa a partir do seu projeto natural e da busca por escolhas coerentes com ele. Na cultura da empresa, ela inspira a visão humanista de liderança e formação de pessoas.$q$, $q$Use o conceito como convite à reflexão: pergunte-se se suas escolhas de trabalho são coerentes com o que você é e com o que a empresa propõe.$q$, $q$Em Si ôntico; Formação de pessoas$q$, 'aprovada'),
($q$ONT-002$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$O que é o 'Em Si ôntico'?$q$, $q$Em Si ôntico; núcleo; natureza; essência; projeto$q$, $q$Na Ontopsicologia, é o núcleo de cada pessoa, o seu projeto natural, que funciona como referência interna para escolher o que é adequado a ela.$q$, $q$Antes de uma escolha importante, reserve um momento para perguntar o que realmente faz sentido para você, além de pressões e opiniões.$q$, $q$Intuição; Autoconhecimento$q$, 'aprovada'),
($q$ONT-003$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$Posso usar a intuição para decidir no trabalho?$q$, $q$intuição; decidir; decisão; sentir; escolha$q$, $q$A escola considera a intuição uma fonte valiosa de informação sobre qual escolha é mais adequada. Ela completa a análise lógica, não a substitui.$q$, $q$Reúna dados, pense nas opções e observe o que sua intuição indica. Se houver conflito, investigue o motivo antes de decidir.$q$, $q$Em Si ôntico; Decisões$q$, 'aprovada'),
($q$ONT-004$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$O que é a 'unidade de ação'?$q$, $q$unidade de ação; pessoa; coerência; ação$q$, $q$Na escola, a unidade de ação é a pessoa como um todo: pensamento, sentimento e ação trabalhando juntos. Na empresa, a expressão também descreve equipes alinhadas a um mesmo objetivo.$q$, $q$Verifique se o que você pensa, sente e faz está na mesma direção. Se não, converse com seu líder sobre o que o está travando.$q$, $q$Unidade de ação (equipe); Coerência$q$, 'aprovada'),
($q$ONT-005$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$O que significa liderar, segundo essa visão?$q$, $q$liderar; liderança; servir; harmonia$q$, $q$O líder é quem sabe servir, fazer funcionar e construir harmonia nas relações para que o grupo produza o máximo de valor. Liderar não é sufocar, vigiar ou pressionar.$q$, $q$Pergunte à equipe de que apoio ela precisa, organize as condições de trabalho e deixe claro o objetivo comum.$q$, $q$Saber servir; Liderança$q$, 'aprovada'),
($q$ONT-006$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$Como um líder constrói harmonia na equipe?$q$, $q$harmonia; relações; equipe; funcionalidade$q$, $q$A harmonia nasce quando cada parte funciona bem e se sente respeitada. O líder é funcional a todas as partes, até que se alinhem a um objetivo simples e comum.$q$, $q$Escute cada área, identifique o que está travando a relação entre elas e ajude a ajustar rotinas e combinados.$q$, $q$Unidade de ação; Relacionamentos$q$, 'aprovada'),
($q$ONT-007$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$Por que um líder precisa de cultura geral?$q$, $q$cultura geral; conhecimento; informação; ambiente$q$, $q$O líder opera no meio de interesses humanos e precisa conhecer o ambiente e as pessoas com quem trabalha: o contexto do país, da região e da cultura.$q$, $q$Leia sobre temas variados, converse com pessoas de áreas e histórias diferentes e traga isso para a forma como lidera.$q$, $q$Atualização; Visão global$q$, 'aprovada'),
($q$ONT-008$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$Por que um líder precisa dominar o próprio setor?$q$, $q$cultura específica; especialista; setor; conhecimento técnico$q$, $q$A inteligência no próprio campo de atuação sustenta o crescimento. Quem lidera deve conhecer bem a teoria e a prática da sua área.$q$, $q$Estude os processos do seu setor, acompanhe a rotina na prática e converse com quem executa para entender os detalhes.$q$, $q$Formação; Excelência$q$, 'aprovada'),
($q$ONT-009$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$Como lidar bem com pessoas de culturas e ambientes diferentes?$q$, $q$diplomacia; relações; respeito; culturas; trato$q$, $q$A habilidade de se relacionar bem, sem ofender e sem destruir valores alheios, faz parte da formação do líder.$q$, $q$Ouça antes de julgar, aprenda os costumes de quem trabalha com você e seja claro e respeitoso ao discordar.$q$, $q$Respeito; Comunicação$q$, 'aprovada'),
($q$ONT-010$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$O que significa 'transcender estereótipos'?$q$, $q$estereótipos; rótulos; preconceito; opinião pronta$q$, $q$É não se prender a opiniões prontas, rótulos e tradições rígidas, para ver cada situação como ela é. Isso não significa abrir mão dos valores da empresa.$q$, $q$Quando pensar 'isso sempre foi assim' ou 'essa pessoa é assim', pergunte quais fatos sustentam o que pensa.$q$, $q$Mente aberta; Valores$q$, 'aprovada'),
($q$ONT-011$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$Quando algo não vai bem, por onde começo?$q$, $q$autoanálise; responsabilidade; começar por mim; causa$q$, $q$A escola propõe começar analisando a si mesmo antes de atribuir a causa aos outros, porque é onde se tem mais poder de mudança.$q$, $q$Pergunte-se o que você pode mudar na situação, ajuste o que está ao seu alcance e depois converse com os outros.$q$, $q$Responsabilidade; Autoconhecimento$q$, 'aprovada'),
($q$ONT-012$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$Como evitar julgar colegas por rótulos?$q$, $q$rótulo; julgar; pré-julgamento; colega$q$, $q$Rótulos simplificam as pessoas e escondem o que cada uma tem de singular.$q$, $q$Observe o que a pessoa faz, pergunte sobre sua forma de trabalhar e avalie com base em fatos e resultados.$q$, $q$Respeito; Relacionamentos$q$, 'aprovada'),
($q$ONT-013$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$Como separar opinião de realidade ao decidir?$q$, $q$opinião; realidade; fatos; fantasia; certeza$q$, $q$Na consciência convivem fantasias, opiniões e certezas. O desafio é identificar qual escolha é realmente concreta e adequada.$q$, $q$Separe o que é fato, o que é interpretação e o que é desejo. Decida com base no que pode ser verificado e na coerência com o objetivo.$q$, $q$Decisões; Clareza$q$, 'aprovada'),
($q$ONT-014$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$Meu corpo reage a certas decisões. Devo prestar atenção?$q$, $q$sinais internos; reação; corpo; incômodo; escolha$q$, $q$A escola ensina que as reações internas diante de uma escolha trazem informações sobre ela. São pistas, não verdades absolutas.$q$, $q$Perceba como se sente ao pensar em cada opção, anote e confirme com fatos e conversa com alguém de confiança.$q$, $q$Intuição; Autoconhecimento$q$, 'aprovada'),
($q$ONT-015$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$Sinto-me disperso e sem foco. O que fazer?$q$, $q$dispersão; foco; caos; confusão; essencial$q$, $q$A dispersão aparece quando se perde a referência do que é essencial e importante.$q$, $q$Volte ao seu objetivo principal, liste o que o aproxima ou afasta dele e elimine o que for ruído.$q$, $q$Foco; Propósito$q$, 'aprovada'),
($q$ONT-016$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$O que é 'campo semântico'?$q$, $q$campo semântico; clima; ambiente; informação; relações$q$, $q$Na Ontopsicologia, é a informação que as pessoas e os ambientes emitem e que influencia as relações. Na prática, é perceber como o clima e as pessoas afetam o seu trabalho.$q$, $q$Observe o ambiente com atenção, converse e confirme com fatos. Nunca use essa percepção sozinha para rotular ou excluir alguém.$q$, $q$Clima de equipe; Comunicação$q$, 'aprovada'),
($q$ONT-017$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$O que é o 'monitor de deflexão'?$q$, $q$monitor de deflexão; desvio; padrões impostos; imitação$q$, $q$Na escola, é o nome dado ao mecanismo que desvia a pessoa do seu projeto natural e a leva a seguir padrões que não são seus. É um conceito técnico que precisa de estudo.$q$, $q$Pergunte-se se uma escolha vem de convicção própria ou de imitação do que os outros esperam. Procure aprofundar o tema em formação adequada.$q$, $q$Em Si ôntico; Autoconhecimento$q$, 'aprovada'),
($q$ONT-018$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$Como encontrar a solução certa para cada situação?$q$, $q$solução certa; proporção; situação; encontrar saída$q$, $q$O líder sabe ler a proporção da realidade e aplicar a solução adequada a cada momento, sem fórmulas prontas.$q$, $q$Entenda bem o contexto, pergunte a quem está na linha de frente e teste a solução em pequena escala antes de ampliar.$q$, $q$Decisões; Melhoria contínua$q$, 'aprovada'),
($q$ONT-019$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$Como me comportar ao entrar no território de outra área?$q$, $q$outra área; território; respeito; servir; obedecer$q$, $q$Um líder reconhece outro líder pelo modo como serve e respeita quando entra no espaço dele.$q$, $q$Peça licença, pergunte como podem se ajudar, siga as regras do local e valorize o que a outra área faz.$q$, $q$Respeito; Saber servir$q$, 'aprovada'),
($q$ONT-020$q$, $q$Ontopsicologia$q$, $q$Ontopsicologia$q$, $q$Liderar é mandar e cobrar?$q$, $q$mandar; cobrar; autoritarismo; comando; liderança$q$, $q$Esse é um conceito imaturo de liderança. Quem lidera de verdade serve, organiza e ajuda as pessoas a produzirem melhor.$q$, $q$Substitua a ordem seca por clareza de objetivo, apoio e acompanhamento. Cobre resultados, mas com respeito.$q$, $q$Liderança; Respeito$q$, 'aprovada')
